const host=window.parent,doc=host.document;
for(const id of ['mnemosyne-t05-launch','mnemosyne-t05-inspect','mnemosyne-t05-read-control'])doc.getElementById(id)?.remove();
const box=doc.createElement('section');box.id='mnemosyne-t05-read-control';
box.style.cssText='position:fixed;top:12px;right:12px;z-index:10003;background:#20242d;color:white;padding:12px;max-width:90vw;max-height:60vh;overflow:auto;border:1px solid #899';
const button=doc.createElement('button');button.textContent='T-05：只读完成工作台验收（点一次）';
const status=doc.createElement('pre');status.id='mnemosyne-t05-read-status';status.textContent='等待点击。仅使用刚才已导入的4条合成正文，不重导。';status.style.cssText='white-space:pre-wrap;overflow-wrap:anywhere';
const close=doc.createElement('button');close.textContent='收起入口';close.onclick=()=>box.remove();
box.append(button,status,close);doc.body.append(box);
button.onclick=()=>{button.disabled=true;status.textContent='加载独立版本模块中…';
const script=doc.createElement('script');script.type='module';script.src='http://127.0.0.1:19375/t05-8650107/packages/workbench/native-read-launch.mjs';
script.onerror=()=>{status.textContent='模块加载失败；请通知Codex，不要重试或刷新。';};doc.body.append(script);};
const cleanup=()=>box.remove();
window.addEventListener("pagehide",cleanup,{once:true});
window.addEventListener("unload",cleanup,{once:true});
